let n;
let m;
let result;

function in() {
    const input = require('readline').createInterface({
        input: process.stdin
    });
    let line = '';
    input.on('line', (data) => {
        line = data;
        input.close();
    });
    input.on('close', () => {
        const parts = line.trim().split(/\s+/);
        n = parseInt(parts[0], 10);
        m = parseInt(parts[1], 10);
        run();
        out();
    });
}

function out() {
    console.log(result);
}

function run() {
    let remain = n;
    let d = 1;
    while (remain > 0) {
        if (d % m !== 0) {
            remain--;
        }
        d++;
    }
    result = d - 1;
}

in();
